 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False]*w for _ in range(h)]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r,c)])
            seen[r][c] = True
            cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]!=0:
                        seen[ny][nx]=True; q.append((ny,nx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            rings=[]
            a,b,d,e=r0,r1,c0,c1
            while a<=b and d<=e:
                color=grid[a][d]
                if any(grid[a][x]!=color for x in range(d,e+1)) or any(grid[b][x]!=color for x in range(d,e+1)) or any(grid[y][d]!=color or grid[y][e]!=color for y in range(a,b+1)):
                    break
                rings.append((a,b,d,e,color))
                if a==b or d==e: break
                a+=1; b-=1; d+=1; e-=1
            if len(rings)<2: continue
            colors=[z[4] for z in rings]
            for i,(a,b,d,e,_) in enumerate(rings):
                color=colors[-1-i]
                for y in range(a,b+1):
                    for x in range(d,e+1):
                        if i==0 or (a+1<=y<=b-1 and d+1<=x<=e-1):
                            out[y][x]=color
    return out

if __name__ == '__main__':
    pass

